"""Click-to-load third-party player; no game executable is copied or hosted."""
from build_pokebonk import ext, ref

P='/poke-survivor/'
SOURCE='https://pokesurvivor.pro/play?embed=1'

def player_body():
    return f'''<nav class="crumbs" aria-label="Breadcrumb" data-play-background><a href="{P}">PokéSurvivor</a> / Play</nav>
<header class="play-intro" id="guide" data-play-background><p class="eyebrow">Ready for the next wave?</p><h1>Play Poke Survivor online</h1><p>A partner. A forest. A growing horde.<br>Load the game below and start a guest run.</p></header>
<section class="game-panel" id="game-panel" aria-label="Poke Survivor game" data-mode="normal">
<div class="game-screen"><div class="game-cover" id="game-cover"><div><span class="play-emblem" aria-hidden="true">▶</span><p class="play-kicker">BROWSER SURVIVAL · THIRD-PARTY EDITION</p><h2>Your next run starts here.</h2><p>Choose a partner, keep moving and let your active move attack.</p><button class="play-button" id="game-launch" type="button">▶ &nbsp; Play now</button><p class="cover-note">Click to connect to pokesurvivor.pro.<br>Its game, account and storage services load only after you press Play.</p></div></div>
<iframe id="game-frame" title="Poke Survivor third-party game hosted by pokesurvivor.pro" data-src="{SOURCE}" allow="autoplay; fullscreen; gamepad" allowfullscreen sandbox="allow-scripts allow-same-origin allow-forms allow-pointer-lock allow-orientation-lock" referrerpolicy="strict-origin-when-cross-origin" hidden></iframe></div>
<div class="game-meta"><p><strong>Hosted by pokesurvivor.pro.</strong> This is a third-party edition, separate from the creator’s pokesurvivor.com. Do not assume accounts or saves transfer.</p><div class="game-tools"><button id="game-expand" type="button" aria-pressed="false" disabled>Expand game</button><button id="game-minimize" type="button" aria-expanded="true" aria-controls="game-panel" disabled>Hide game</button>{ext(SOURCE,'Open pokesurvivor.pro')}{ext('https://pokesurvivor.com/en/','Original: pokesurvivor.com')}</div><p id="game-status" role="status">Game not loaded. Pause inside the game before hiding it; hiding does not pause a run.</p></div></section>
<div class="game-dock" id="game-dock" hidden><span>Game is hidden · pause in-game first</span><button id="game-restore" type="button">Return to game ↑</button></div>
<div class="play-notes" data-play-background><nav class="play-jump" aria-label="Play help"><a href="#controls">Controls</a><a href="#edition">Edition &amp; saves</a><a href="#loading">Loading help</a></nav>
<section id="controls"><h2>Move first. Keep a route open.</h2><p>Choose <strong>Play as guest</strong>, answer the partner questions, accept or change your partner, then choose <strong>Play</strong> in the game menu.</p><div class="control-grid"><p><b>WASD / arrows</b>Move your partner</p><p><b>1–4 / Q–E</b>Change active attack</p><p><b>Esc / P</b>Pause inside the game</p></div><p>On a phone, rotate to landscape and drag in the game area. Expand gives the game more room. If keyboard input scrolls this page, click inside the game first. Exit expanded view with its visible button; Esc may be handled by the game while it has focus.</p><p>Hide keeps the same game frame loaded so you can read below. <strong>Pause first.</strong> Reloading or leaving this page ends the current session.</p></section>
<section id="edition"><h2>Know which edition you are playing.</h2><p>The embedded game is supplied by pokesurvivor.pro, an independent host.{ref(1)} It is not the creator’s original site and its exact parity with the current original build is unverified. Our other guides name the original source version they cover; hosted editions can differ.</p><p>On October 26, 2026, our desktop Chrome cross-site check completed guest setup, selected Scorbunny and entered a short run: the timer reached 00:09, movement worked and the defeat counter reached 1. This checks startup, not a complete run, multiplayer, cloud saves or account transfer. Mobile layout checks are browser simulations, not physical-phone benchmarks.</p><p>The host labels guest progress as not saved to an account. Keep existing progress at its original address and browser profile. For the creator’s edition, use {ext('https://pokesurvivor.com/en/','pokesurvivor.com')} instead.{ref(2)} We cannot access either provider’s game accounts or recover their saves.</p></section>
<section id="loading"><h2>If the game does not start</h2><ol><li>Wait for the menu inside the window; the outer page loading does not confirm the game is ready.</li><li>Try <strong>Open pokesurvivor.pro ↗</strong> above to check the same host in its own tab. A separate tab may have different storage access.</li><li>If that host is unavailable, open the original pokesurvivor.com link. It is a separate edition, so do not expect this session to follow you.</li></ol><p>No JavaScript? Use either direct game link above. See our <a href="{P}privacy/">privacy notice</a> for what connects when you load this third-party game.</p></section>
<section class="sources" id="sources"><h2>Sources &amp; verification</h2><ol><li id="source-1">{ext(SOURCE,'pokesurvivor.pro — embedded game and host notice')}. Guest menu, controls and short cross-site run checked October 26, 2026. Host-specific behavior; full-run and save compatibility unverified.</li><li id="source-2">{ext('https://pokesurvivor.com/en/','pokesurvivor.com — creator’s original game')}. Separate original entry, checked October 26, 2026; it blocks third-party iframe play.</li></ol><a href="#guide">Back to play ↑</a></section>
<section class="related"><h2>Between runs</h2><a href="{P}beginners-guide/">First-run controls &amp; choices →</a><a href="{P}builds/">Physical &amp; special build checks →</a><a href="{P}save-and-sync/">Save &amp; sync checks →</a></section></div>'''

def make_play_page(shell):
    html=shell(P+'play/','Play Poke Survivor Online | Megabonk.org','Play Poke Survivor in your browser with a click-to-load third-party game, clear controls, expanded view and notes on editions, accounts and saves.',player_body())
    return html.replace('</head>','<link rel="stylesheet" href="/assets/poke-survivor/play.css"><script defer src="/assets/poke-survivor/play.js"></script></head>').replace('<body>','<body class="ps-play-page">')
